// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/ERC20Burnable.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/security/Pausable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/utils/math/Math.sol";

/**
 * @title IPriceOracle
 * @author Chainlink
 * @notice Interface for a Chainlink-compatible price feed oracle.
 */
interface IPriceOracle {
    function latestRoundData()
        external
        view
        returns (
            uint80 roundId,
            int256 answer,
            uint256 startedAt,
            uint256 updatedAt,
            uint80 answeredInRound
        );

    function decimals() external view returns (uint8);
}

/**
 * @title OracleGuardedVault
 * @author Based on a request for an Expert Solidity Engineer
 * @notice A tokenized vault (ERC4626-like) for an underlying ERC20 asset.
 * It issues shares proportional to the assets deposited. The vault incorporates
 * several security features:
 * - A circuit breaker that halts deposits and withdrawals if the external oracle price
 *   deviates beyond a configurable threshold (`maxDrawdownBps`).
 * - Daily net flow limits to cap the total assets deposited or withdrawn in a 24-hour period.
 * - Pausable functionality controlled by a MANAGER_ROLE.
 * - Management fees that accrue to a treasury address.
 *
 * This contract uses OpenZeppelin's AccessControl for role-based permissions,
 * ReentrancyGuard for preventing reentrancy attacks, and SafeERC20 for safe
 * token interactions. It is designed for EVM-compatible networks like Camp (BaseCAMP).
 */
contract OracleGuardedVault is ERC20, ERC20Burnable, AccessControl, Pausable, ReentrancyGuard {
    using SafeERC20 for IERC20;
    using Math for uint256;

    /*///////////////////////////////////////////////////////////////
                                 EVENTS
    //////////////////////////////////////////////////////////////*/

    event Deposit(address indexed caller, address indexed owner, uint256 assets, uint256 shares);
    event Withdraw(
        address indexed caller,
        address indexed owner,
        address indexed receiver,
        uint256 assets,
        uint256 shares
    );
    event FeeAccrued(uint256 feeAmountAssets, uint256 feeSharesMinted);
    event OracleUpdated(address indexed newOracle);
    event TreasuryUpdated(address indexed newTreasury);
    event FeesUpdated(uint256 newManagementFeeBps);
    event LimitsUpdated(uint256 newDepositLimit, uint256 newWithdrawalLimit);
    event MaxDrawdownUpdated(uint256 newMaxDrawdownBps);
    event MaxPriceAgeUpdated(uint256 newMaxPriceAge);

    /*///////////////////////////////////////////////////////////////
                                 ROLES
    //////////////////////////////////////////////////////////////*/

    bytes32 public constant MANAGER_ROLE = keccak256("MANAGER_ROLE");

    /*///////////////////////////////////////////////////////////////
                            STATE VARIABLES
    //////////////////////////////////////////////////////////////*/

    /// @notice The underlying token this vault holds.
    IERC20 public immutable underlying;
    /// @notice The external price feed oracle.
    IPriceOracle public oracle;
    /// @notice The address where fees are sent.
    address public treasury;

    // --- Fees ---
    /// @notice Annual management fee in basis points (1/10000).
    uint256 public managementFeeBps;
    /// @notice The timestamp of the last fee accrual.
    uint256 public lastFeeAccrualTimestamp;

    // --- Daily Limits ---
    /// @notice Maximum net assets that can be deposited in a 24-hour window.
    uint256 public dailyDepositLimit;
    /// @notice Maximum net assets that can be withdrawn in a 24-hour window.
    uint256 public dailyWithdrawalLimit;
    /// @notice Net asset flow for the current day (deposits - withdrawals).
    int256 public netFlowToday;
    /// @notice The start of the current 24-hour window, in days since epoch.
    uint256 public currentDay;

    // --- Circuit Breaker ---
    /// @notice The last recorded price from the oracle.
    int256 public lastPrice;
    /// @notice The timestamp of the last recorded price.
    uint256 public lastPriceTimestamp;
    /// @notice Maximum price deviation allowed in basis points before circuit breaker trips.
    uint256 public maxDrawdownBps;
    /// @notice Maximum age of an oracle price update to be considered valid.
    uint256 public maxPriceAge;

    // --- Constants ---
    uint256 private constant BPS_DENOMINATOR = 10_000;
    uint256 private constant SECONDS_PER_YEAR = 365 days;

    /*///////////////////////////////////////////////////////////////
                               CONSTRUCTOR
    //////////////////////////////////////////////////////////////*/

    constructor(
        address underlyingAsset,
        string memory name,
        string memory symbol,
        address initialOracle,
        address initialTreasury
    ) ERC20(name, symbol) {
        require(underlyingAsset != address(0), "Vault: zero address underlying");
        require(initialOracle != address(0), "Vault: zero address oracle");
        require(initialTreasury != address(0), "Vault: zero address treasury");

        underlying = IERC20(underlyingAsset);
        oracle = IPriceOracle(initialOracle);
        treasury = initialTreasury;

        lastFeeAccrualTimestamp = block.timestamp;
        currentDay = block.timestamp / 1 days;

        _setupRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _setupRole(MANAGER_ROLE, msg.sender);
    }

    /*///////////////////////////////////////////////////////////////
                           ERC4626-LIKE VIEWS
    //////////////////////////////////////////////////////////////*/

    /** @notice The address of the underlying asset token. */
    function asset() public view returns (address) {
        return address(underlying);
    }

    /** @notice The total amount of underlying assets held by the vault. */
    function totalAssets() public view virtual returns (uint256) {
        return underlying.balanceOf(address(this));
    }

    /** @notice Calculates the amount of shares that would be minted for `assets`. */
    function convertToShares(uint256 assets) public view virtual returns (uint256) {
        uint256 supply = totalSupply();
        return (supply == 0) ? assets : assets.mulDiv(supply, totalAssets(), Math.Rounding.Down);
    }

    /** @notice Calculates the amount of assets that `shares` are worth. */
    function convertToAssets(uint256 shares) public view virtual returns (uint256) {
        uint256 supply = totalSupply();
        return (supply == 0) ? shares : shares.mulDiv(totalAssets(), supply, Math.Rounding.Down);
    }

    /** @notice The maximum amount of underlying assets that can be deposited. */
    function maxDeposit(address) public view virtual returns (uint256) {
        (uint256 remainingDepositLimit, ) = remainingDailyLimits();
        return remainingDepositLimit;
    }

    /** @notice The maximum amount of shares that can be minted. */
    function maxMint(address owner) public view virtual returns (uint256) {
        return convertToShares(maxDeposit(owner));
    }

    /** @notice The maximum amount of underlying assets that can be withdrawn by `owner`. */
    function maxWithdraw(address owner) public view virtual returns (uint256) {
        ( , uint256 remainingWithdrawalLimit) = remainingDailyLimits();
        return Math.min(convertToAssets(balanceOf(owner)), remainingWithdrawalLimit);
    }

    /** @notice The maximum amount of shares that can be redeemed from `owner`. */
    function maxRedeem(address owner) public view virtual returns (uint256) {
        return convertToShares(maxWithdraw(owner));
    }

    /** @notice Preview the amount of shares to be received for a deposit of `assets`. */
    function previewDeposit(uint256 assets) public view virtual returns (uint256) {
        return convertToShares(assets);
    }

    /** @notice Preview the amount of assets needed to mint `shares`. */
    function previewMint(uint256 shares) public view virtual returns (uint256) {
        return convertToAssets(shares);
    }

    /** @notice Preview the amount of shares needed to withdraw `assets`. */
    function previewWithdraw(uint256 assets) public view virtual returns (uint256) {
        return convertToShares(assets);
    }

    /** @notice Preview the amount of assets to be received for redeeming `shares`. */
    function previewRedeem(uint256 shares) public view virtual returns (uint256) {
        return convertToAssets(shares);
    }

    /*///////////////////////////////////////////////////////////////
                           CUSTOM VIEW FUNCTIONS
    //////////////////////////////////////////////////////////////*/

    /** @notice Returns the remaining deposit and withdrawal capacity for the day. */
    function remainingDailyLimits() public view returns (uint256 depositRemaining, uint256 withdrawRemaining) {
        uint256 day = block.timestamp / 1 days;
        int256 netFlow = (day == currentDay) ? netFlowToday : int256(0);

        if (netFlow >= 0) {
            depositRemaining = dailyDepositLimit - uint256(netFlow);
            withdrawRemaining = dailyWithdrawalLimit;
        } else {
            depositRemaining = dailyDepositLimit;
            withdrawRemaining = dailyWithdrawalLimit - uint256(-netFlow);
        }
    }

    /** @notice Returns the status of the price deviation circuit breaker. */
    function getCircuitBreakerStatus() public view returns (int256 price, uint256 timestamp, bool isTripped) {
        if (oracle == IPriceOracle(address(0)) || maxDrawdownBps == 0 || lastPriceTimestamp == 0) {
            return (lastPrice, lastPriceTimestamp, false);
        }
        ( , int256 currentPrice, , , ) = oracle.latestRoundData();
        uint256 priceDiff = _abs(currentPrice - lastPrice);
        isTripped = priceDiff * BPS_DENOMINATOR > _abs(lastPrice) * maxDrawdownBps;
        return (lastPrice, lastPriceTimestamp, isTripped);
    }

    /*///////////////////////////////////////////////////////////////
                           USER-FACING FUNCTIONS
    //////////////////////////////////////////////////////////////*/

    /**
     * @notice Deposits `assets` amount of underlying token and mints shares to `receiver`.
     * @param assets The amount of underlying tokens to deposit.
     * @param receiver The address to receive the vault shares.
     * @return shares The amount of shares minted.
     */
    function deposit(uint256 assets, address receiver) public virtual nonReentrant returns (uint256 shares) {
        _checkAndAccrue();
        (int256 currentPrice, uint256 priceTimestamp) = _checkCircuitBreaker();

        shares = previewDeposit(assets);
        require(shares > 0, "Vault: zero shares minted");

        _updateDailyLimits(assets, 0);
        _deposit(msg.sender, receiver, assets, shares);

        lastPrice = currentPrice;
        lastPriceTimestamp = priceTimestamp;

        return shares;
    }

    /**
     * @notice Mints `shares` amount of vault shares to `receiver` by depositing underlying tokens.
     * @param shares The amount of shares to mint.
     * @param receiver The address to receive the vault shares.
     * @return assets The amount of underlying tokens deposited.
     */
    function mint(uint256 shares, address receiver) public virtual nonReentrant returns (uint256 assets) {
        _checkAndAccrue();
        (int256 currentPrice, uint256 priceTimestamp) = _checkCircuitBreaker();

        assets = previewMint(shares);
        require(assets > 0, "Vault: zero assets deposited");

        _updateDailyLimits(assets, 0);
        _deposit(msg.sender, receiver, assets, shares);

        lastPrice = currentPrice;
        lastPriceTimestamp = priceTimestamp;

        return assets;
    }

    /**
     * @notice Withdraws `assets` amount of underlying tokens by burning shares from `owner`.
     * @param assets The amount of underlying assets to withdraw.
     * @param receiver The address to receive the underlying assets.
     * @param owner The address from which to burn vault shares.
     * @return shares The amount of shares burned.
     */
    function withdraw(uint256 assets, address receiver, address owner) public virtual nonReentrant returns (uint256 shares) {
        _checkAndAccrue();
        (int256 currentPrice, uint256 priceTimestamp) = _checkCircuitBreaker();

        shares = previewWithdraw(assets);
        require(shares <= maxRedeem(owner), "Vault: withdraw exceeds balance");

        _updateDailyLimits(0, assets);
        _withdraw(msg.sender, receiver, owner, assets, shares);

        lastPrice = currentPrice;
        lastPriceTimestamp = priceTimestamp;

        return shares;
    }

    /**
     * @notice Redeems `shares` from `owner` for underlying assets.
     * @param shares The amount of shares to redeem.
     * @param receiver The address to receive the underlying assets.
     * @param owner The address from which to burn vault shares.
     * @return assets The amount of underlying assets withdrawn.
     */
    function redeem(uint256 shares, address receiver, address owner) public virtual nonReentrant returns (uint256 assets) {
        _checkAndAccrue();
        (int256 currentPrice, uint256 priceTimestamp) = _checkCircuitBreaker();

        assets = previewRedeem(shares);
        require(assets <= maxWithdraw(owner), "Vault: redeem exceeds balance");

        _updateDailyLimits(0, assets);
        _withdraw(msg.sender, receiver, owner, assets, shares);

        lastPrice = currentPrice;
        lastPriceTimestamp = priceTimestamp;

        return assets;
    }

    /*///////////////////////////////////////////////////////////////
                             MANAGER FUNCTIONS
    //////////////////////////////////////////////////////////////*/

    function pause() public virtual onlyRole(MANAGER_ROLE) {
        _pause();
    }

    function unpause() public virtual onlyRole(MANAGER_ROLE) {
        _unpause();
    }

    function setOracle(address newOracle) public virtual onlyRole(MANAGER_ROLE) {
        require(newOracle != address(0), "Vault: zero address");
        oracle = IPriceOracle(newOracle);
        emit OracleUpdated(newOracle);
    }

    function setTreasury(address newTreasury) public virtual onlyRole(MANAGER_ROLE) {
        require(newTreasury != address(0), "Vault: zero address");
        treasury = newTreasury;
        emit TreasuryUpdated(newTreasury);
    }

    function setFees(uint256 newManagementFeeBps) public virtual onlyRole(MANAGER_ROLE) {
        _accrueManagementFee(); // Accrue fees before changing rate
        require(newManagementFeeBps <= BPS_DENOMINATOR, "Vault: fee too high");
        managementFeeBps = newManagementFeeBps;
        emit FeesUpdated(newManagementFeeBps);
    }

    function setLimits(uint256 newDepositLimit, uint256 newWithdrawalLimit) public virtual onlyRole(MANAGER_ROLE) {
        dailyDepositLimit = newDepositLimit;
        dailyWithdrawalLimit = newWithdrawalLimit;
        emit LimitsUpdated(newDepositLimit, newWithdrawalLimit);
    }

    function setMaxDrawdown(uint256 newMaxDrawdownBps) public virtual onlyRole(MANAGER_ROLE) {
        require(newMaxDrawdownBps <= BPS_DENOMINATOR, "Vault: drawdown too high");
        maxDrawdownBps = newMaxDrawdownBps;
        emit MaxDrawdownUpdated(newMaxDrawdownBps);
    }

    function setMaxPriceAge(uint256 newMaxPriceAge) public virtual onlyRole(MANAGER_ROLE) {
        require(newMaxPriceAge > 0, "Vault: max price age must be > 0");
        maxPriceAge = newMaxPriceAge;
        emit MaxPriceAgeUpdated(newMaxPriceAge);
    }

    /** @notice Triggers a manual accrual and collection of management fees. */
    function collectManagementFees() public virtual onlyRole(MANAGER_ROLE) {
        _accrueManagementFee();
    }

    /*///////////////////////////////////////////////////////////////
                          INTERNAL AND HOOKS
    //////////////////////////////////////////////////////////////*/

    /** @dev Hook to enforce Pausable. */
    function _beforeTokenTransfer(address from, address to, uint256 amount) internal virtual override {
        super._beforeTokenTransfer(from, to, amount);
        _requireNotPaused();
    }

    function _checkAndAccrue() internal {
        _accrueManagementFee();
        _resetDailyLimitsIfNeeded();
    }

    function _checkCircuitBreaker() internal view returns (int256 currentPrice, uint256 priceTimestamp) {
        require(address(oracle) != address(0), "Vault: oracle not set");
        ( , int256 price, , uint256 updatedAt, ) = oracle.latestRoundData();
        require(updatedAt > 0, "Vault: invalid oracle round");
        require(maxPriceAge > 0 && block.timestamp - updatedAt <= maxPriceAge, "Vault: stale oracle price");

        currentPrice = price;
        priceTimestamp = updatedAt;

        if (lastPriceTimestamp != 0 && maxDrawdownBps > 0) {
            uint256 priceDiff = _abs(currentPrice - lastPrice);
            require(
                priceDiff * BPS_DENOMINATOR <= _abs(lastPrice) * maxDrawdownBps,
                "Vault: price deviation too high"
            );
        }
    }

    function _resetDailyLimitsIfNeeded() internal {
        uint256 day = block.timestamp / 1 days;
        if (day > currentDay) {
            currentDay = day;
            netFlowToday = 0;
        }
    }

    function _updateDailyLimits(uint256 assetsIn, uint256 assetsOut) internal {
        int256 flow = int256(assetsIn) - int256(assetsOut);
        int256 newNetFlow = netFlowToday + flow;

        if (newNetFlow > 0) {
            require(uint256(newNetFlow) <= dailyDepositLimit, "Vault: deposit limit exceeded");
        } else {
            require(uint256(-newNetFlow) <= dailyWithdrawalLimit, "Vault: withdrawal limit exceeded");
        }
        netFlowToday = newNetFlow;
    }

    function _accrueManagementFee() internal {
        if (block.timestamp <= lastFeeAccrualTimestamp || managementFeeBps == 0) {
            return;
        }

        uint256 timeElapsed = block.timestamp - lastFeeAccrualTimestamp;
        uint256 currentAssets = totalAssets();

        if (currentAssets == 0) {
            lastFeeAccrualTimestamp = block.timestamp;
            return;
        }

        uint256 feeAmountAssets = (currentAssets * managementFeeBps * timeElapsed) / (BPS_DENOMINATOR * SECONDS_PER_YEAR);

        if (feeAmountAssets > 0) {
            uint256 feeShares = convertToShares(feeAmountAssets);
            if (feeShares > 0) {
                _mint(treasury, feeShares);
                emit FeeAccrued(feeAmountAssets, feeShares);
            }
        }
        lastFeeAccrualTimestamp = block.timestamp;
    }

    function _deposit(address caller, address receiver, uint256 assets, uint256 shares) internal {
        require(receiver != address(0), "Vault: receiver is zero address");
        underlying.safeTransferFrom(caller, address(this), assets);
        _mint(receiver, shares);
        emit Deposit(caller, receiver, assets, shares);
    }

    function _withdraw(address caller, address receiver, address owner, uint256 assets, uint256 shares) internal {
        require(receiver != address(0), "Vault: receiver is zero address");
        if (caller != owner) {
            _spendAllowance(owner, caller, shares);
        }
        _burn(owner, shares);
        underlying.safeTransfer(receiver, assets);
        emit Withdraw(caller, owner, receiver, assets, shares);
    }

    function _abs(int256 x) private pure returns (uint256) {
        return uint256(x >= 0 ? x : -x);
    }
}

